@patch
def href(self:Table, 
         this_href:str,   # href text
         link:str='link'  # link text
        )->str:   # Latex-formatted href 
    if this_href is np.NaN:
        return ""
    else:
        return f"\\href{{{this_href}}}{{[{link}]}}"
